   const charge=db.records.find(x=>x.entity_id===p.chargeId&&x.clinic===c&&x.entity_type==='cobranca');if(!charge||!ClinicAuth.canRead(charge,c))deny();
   const d=JSON.parse(charge.payload);if(!Number.isFinite(p.amountCents)||p.amountCents<=0||p.amountCents>d.amountCents-(d.paidCents||0))throw Error('Valor inválido');
